<?php require 'koneksi.php'; $msg=$_GET['msg']??''; $err=$_GET['err']??''; ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lupa Password</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="login-body"><div class="login-box"><div class="login-brand">📚 perpustakaan_digital_kelompok3</div><h3>Lupa Password Siswa</h3><?php if($err):?><div class="alert-danger"><?=htmlspecialchars($err)?></div><?php endif;?><?php if($msg):?><div class="alert-success"><?=htmlspecialchars($msg)?></div><?php endif;?><form method="post" action="proses_siswa_lupa_password.php"><div class="form-group"><label>NISN</label><input class="form-control" name="identitas" required></div><div class="form-group"><label>Password Baru</label><div class="password-wrap"><input class="form-control" type="password" id="newPassword" name="password" minlength="6" required><button type="button" class="toggle-password" onclick="togglePassword('newPassword',this)" aria-label="Tampilkan Password Baru">👁</button></div></div><div class="form-group"><label>Konfirmasi Password Baru</label><div class="password-wrap"><input class="form-control" type="password" id="confirmPassword" name="konfirmasi" minlength="6" required><button type="button" class="toggle-password" onclick="togglePassword('confirmPassword',this)" aria-label="Tampilkan Konfirmasi Password Baru">👁</button></div></div><button class="btn btn-primary">Reset Password</button></form><p style="margin-top:15px"><a href="siswa_login.php">Kembali Login</a></p></div><script>function togglePassword(id,btn){const i=document.getElementById(id);if(i.type==='password'){i.type='text';btn.textContent='🙈';}else{i.type='password';btn.textContent='👁';}}</script></body></html>
